#!/usr/bin/env bash
# Rebuild FaceBoxes CPU NMS against the active NumPy.
# The previously checked-in nms/cpu_nms.c was generated by Cython 3.0.12 from
# NumPy 1.x __init__.cython-30.pxd and reads PyArray_Descr.subarray, which
# NumPy 2 removed. Delete it so this build cannot compile that stale file.
set -eu
rm -f nms/cpu_nms.c
python3 build.py build_ext --inplace --force
